Python 3.12+ code:

def inner():
    try:
        yield 1
        yield 2
    finally:
        print('inner-finally')

def outer():
    try:
        try:
            yield from inner()
        except ValueError:
            print('caught')
            yield 9
    finally:
        print('outer-finally')

g = outer()
print(next(g))
print(g.throw(ValueError()))
g.close()
